class stringx;

class vm_executable {
public:
  const stringx& get_fullname() const;
};

class script_object {
public:
  class instance {
  public:
    const stringx& get_name() const;
  };
};

class vm_thread {
public:
  script_object::instance* get_instance() const;
  const vm_executable* get_executable() const;
};

class stringx {};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class vm_stack {
  int salloc;
  char* buffer;
  char* SP;
  vm_thread* my_thread;
protected:
  void move_SP(int n) { SP += n; }
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { move_SP(-n); }
  bool push(const char* src, int n);
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    function(script_library_class*, const char*);
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

typedef float vm_num_t;
typedef float rational_t;

class bitmap_widget {
public:
  virtual rational_t get_height();
};

typedef bitmap_widget* vm_bitmap_widget_t;

class slf_bitmap_widget_get_height_t : public script_library_class::function
{
public:
  slf_bitmap_widget_get_height_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
  struct parms_t
  {
    vm_bitmap_widget_t me;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_num_t result = parms->me->get_height();
    if (!stack.push((char*)&result,sizeof(result)) )
      error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
    return true;
  }
};
